def gen(rng):
    def fmt(v):
        return str(len(v)) + '\n' + ' '.join(map(str, v))
    tests = [fmt([7, 8]), fmt([1, 1]), fmt([10**9, 10**9]), fmt([5, 5, 5, 5]), fmt([1, 2, 3, 4, 5, 6]), fmt([6, 5, 4, 3, 2, 1]), fmt([1, 100, 100, 1])]
    for n in (2, 4, 6, 8, 10, 14, 20, 30):
        for _ in range(2):
            tests.append(fmt([rng.randint(1, 50) for _ in range(n)]))
    for _ in range(3):
        tests.append(fmt([rng.randint(1, 10**9) for _ in range(40)]))
    N = 100000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)]))
    tests.append(fmt([10**9] * N))
    tests.append(fmt(list(range(1, N + 1))))
    tests.append(fmt([rng.randint(1, 10) for _ in range(N)]))
    return tests

